body.data:
{
  "aggregate": "question",
  "pipeline": {{
    (() => {
      const targetDomain = this.params.domain || "";
      return [
        {
          "$match": {
            "domain": targetDomain
          }
        },
        {
          "$lookup": {
            "from": "appsmith_test",
            "let": { "qIdStr": { "$toString": "$_id" } },
            "pipeline": [
              { "$unwind": "$questions" },
              {
                "$match": {
                  "$expr": { "$eq": ["$questions._id", "$$qIdStr"] }
                }
              },
              { "$count": "occurrenceCount" }
            ],
            "as": "testCountData"
          }
        },
        {
          "$addFields": {
            "usageCount": {
              "$ifNull": [{ "$arrayElemAt": ["$testCountData.occurrenceCount", 0] }, 0]
            }
          }
        },
        {
          "$group": {
            "_id": null,
            "minUsage": { "$min": "$usageCount" }
          }
        }
      ];
    })()
  }},
  "cursor": {}
}

